OUT=Path('results/thrml_spw/fine_range_confirmation')
def main():
    OUT.mkdir(exist_ok=True);assert not (OUT/'protocol.json').exists();old=json.loads(Path('results/thrml_spw/sample_allocation/protocol.json').read_text());ranges=json.loads(Path('results/thrml_spw/range_localization/protocol.json').read_text());assert json.loads(Path('results/thrml_spw/range_localization/evidence_audit.json').read_text())['all_predeclared_theory_checks_within20percent']
