    source=old['source_parquets']['test'];assert sha(source['path'])==source['sha256'];tok=AutoTokenizer.from_pretrained(Path(HF_HUB_CACHE)/f"models--distilbert--distilgpt2/snapshots/{old['revision']}",local_files_only=True);texts=pq.read_table(source['path'],columns=['text']).column('text').to_pylist();ids=np.asarray(tok('\n'.join(s for s in texts if s and s.strip()),add_special_tokens=False)['input_ids'],np.int64);used=[np.load(r['path'])[r['key']] for r in history if r['domain']=='test'];used.append(np.array(old['legacy_excluded_test_offsets']));used=np.concatenate(used);eligible=np.arange(len(ids)//65)*65;eligible=eligible[~np.any((eligible[:,None]<used[None]+65)&(used[None]<eligible[:,None]+65),axis=1)];starts=np.sort(np.random.default_rng(2026118001).choice(eligible,32,replace=False));np.savez_compressed(OUT/'tokens.npz',test_tokens=np.stack([ids[i:i+65] for i in starts]),test_token_offsets=starts)
